import numpy as np

def global_avg_pool(x: list) -> np.ndarray:
    arr = np.array(x, dtype=float)
    if arr.ndim == 3:
        return np.round(arr.mean(axis=(1, 2)), 6)
    elif arr.ndim == 4:
        return np.round(arr.mean(axis=(2, 3)), 6)
    return np.round(arr.mean(axis=-1), 6)
